import{_ as t,o as i,c as s,ag as o}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Kit Enseignants","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators.md","filePath":"fr/community/educators.md"}'),r={name:"fr/community/educators.md"};function n(l,e,a,u,d,c){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="kit-enseignants" tabindex="-1">Kit Enseignants <a class="header-anchor" href="#kit-enseignants" aria-label="Permalink to &quot;Kit Enseignants&quot;">​</a></h1><p>LLMxRay est concu pour l&#39;apprentissage. Ce kit aide les enseignants a integrer LLMxRay dans leurs cours d&#39;IA/ML grace a des exercices de laboratoire prets a l&#39;emploi, des guides de deploiement et des pistes d&#39;evaluation.</p><h2 id="pourquoi-llmxray-pour-l-enseignement" tabindex="-1">Pourquoi LLMxRay pour l&#39;enseignement ? <a class="header-anchor" href="#pourquoi-llmxray-pour-l-enseignement" aria-label="Permalink to &quot;Pourquoi LLMxRay pour l&#39;enseignement ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avantage</th><th>Details</th></tr></thead><tbody><tr><td><strong>Gratuit</strong></td><td>Pas de cles API, pas de couts cloud, pas d&#39;abonnements pour les etudiants. Budget zero.</td></tr><tr><td><strong>Local</strong></td><td>Toutes les donnees restent sur la machine de l&#39;etudiant. Aucune preoccupation de confidentialite, aucune politique de donnees institutionnelle a gerer.</td></tr><tr><td><strong>Visuel</strong></td><td>Les etudiants voient les tokens arriver en temps reel, observent la coloration de confiance et explorent les motifs d&#39;attention. Les concepts abstraits deviennent concrets.</td></tr><tr><td><strong>Sur</strong></td><td>Aucun risque que les etudiants fassent exploser une facture cloud ou exposent des donnees sensibles.</td></tr><tr><td><strong>Multiplateforme</strong></td><td>Fonctionne sur Windows, macOS et Linux. Deploiement via npm, Docker ou git clone.</td></tr></tbody></table><h2 id="integration-dans-les-cours" tabindex="-1">Integration dans les cours <a class="header-anchor" href="#integration-dans-les-cours" aria-label="Permalink to &quot;Integration dans les cours&quot;">​</a></h2><p>LLMxRay s&#39;integre naturellement dans :</p><ul><li><strong>Introduction a l&#39;IA/ML</strong> — Comprendre comment les modeles de langage generent du texte</li><li><strong>Traitement du langage naturel</strong> — Analyse de tokens, embeddings, similarite semantique</li><li><strong>Genie logiciel</strong> — Integration d&#39;API, tool calling, prompt engineering</li><li><strong>Science des donnees</strong> — Methodologie de benchmarking, analyse statistique des sorties de modeles</li><li><strong>Ethique de l&#39;IA</strong> — Explorer les biais des modeles a travers les resultats TruthfulQA et la detection d&#39;hallucinations</li></ul><hr><h2 id="exercices-de-laboratoire" tabindex="-1">Exercices de laboratoire <a class="header-anchor" href="#exercices-de-laboratoire" aria-label="Permalink to &quot;Exercices de laboratoire&quot;">​</a></h2><h3 id="exercice-1-exploration-des-tokens" tabindex="-1">Exercice 1 : Exploration des tokens <a class="header-anchor" href="#exercice-1-exploration-des-tokens" aria-label="Permalink to &quot;Exercice 1 : Exploration des tokens&quot;">​</a></h3><p><strong>Objectif :</strong> Comprendre comment la temperature affecte la sortie du modele.</p><p><strong>Duree :</strong> 45 minutes</p><p><strong>Prerequis :</strong> Un modele capable de dialoguer (par ex. <code>llama3.2</code>)</p><p><strong>Instructions :</strong></p><ol><li>Ouvrez Chat Diagnostics et selectionnez un modele</li><li>Envoyez le prompt : &quot;Write a short poem about the ocean&quot;</li><li>Observez le flux de tokens — notez la coloration de confiance (vert = confiant, orange = incertain)</li><li>Ouvrez l&#39;onglet Stream pour visualiser la latence inter-tokens</li><li>Allez dans <strong>Compare</strong> et configurez un Temperature Sweep (3 slots : 0.1, 0.7, 1.5)</li><li>Executez le meme prompt sur les trois temperatures</li><li>Comparez les sorties en Grid View, puis basculez en Diff View</li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Comment la sortie evolue-t-elle a des temperatures plus elevees ?</li><li>Quels tokens montrent une confiance plus faible a la temperature 1.5 par rapport a 0.1 ?</li><li>La &quot;meilleure&quot; sortie est-elle toujours obtenue a la temperature la plus basse ? Pourquoi ou pourquoi pas ?</li></ul><hr><h3 id="exercice-2-comparaison-de-modeles" tabindex="-1">Exercice 2 : Comparaison de modeles <a class="header-anchor" href="#exercice-2-comparaison-de-modeles" aria-label="Permalink to &quot;Exercice 2 : Comparaison de modeles&quot;">​</a></h3><p><strong>Objectif :</strong> Analyser les compromis qualite/vitesse entre differentes tailles de modeles.</p><p><strong>Duree :</strong> 60 minutes</p><p><strong>Prerequis :</strong> Deux modeles de tailles differentes (par ex. <code>llama3.2:1b</code> et <code>llama3.2:3b</code>)</p><p><strong>Instructions :</strong></p><ol><li>Ouvrez <strong>Compare</strong> et creez 2 slots, un par modele, tous deux a temperature 0.7</li><li>Utilisez ce prompt : &quot;Explain how a neural network learns, in simple terms&quot;</li><li>Lancez l&#39;execution et observez le streaming cote a cote</li><li>Consultez la <strong>Metrics Bar</strong> : comparez TTFT, tokens/sec et le nombre total de tokens</li><li>Repetez avec un prompt plus complexe : &quot;Write a Python function to find all prime factors of a number, then explain your approach step by step&quot;</li><li>Notez les metriques pour les deux prompts</li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Quel modele est le plus rapide ? De combien ?</li><li>Le modele plus grand produit-il des reponses sensiblement meilleures ?</li><li>A partir de quel point la difference de qualite justifie-t-elle le cout en vitesse ?</li><li>Comment choisiriez-vous un modele pour un chatbot de production par rapport a un assistant de programmation ?</li></ul><hr><h3 id="exercice-3-benchmarkez-vos-modeles" tabindex="-1">Exercice 3 : Benchmarkez vos modeles <a class="header-anchor" href="#exercice-3-benchmarkez-vos-modeles" aria-label="Permalink to &quot;Exercice 3 : Benchmarkez vos modeles&quot;">​</a></h3><p><strong>Objectif :</strong> Executer des evaluations standardisees et interpreter les resultats.</p><p><strong>Duree :</strong> 90 minutes</p><p><strong>Prerequis :</strong> Un ou deux modeles, suites ARC et TruthfulQA</p><p><strong>Instructions :</strong></p><ol><li>Ouvrez la page <strong>Benchmark</strong></li><li>Selectionnez un modele et lancez la suite ARC-Challenge</li><li>Pendant l&#39;execution, observez la progression en direct et les resultats par question</li><li>Apres la fin de l&#39;execution, analysez les resultats : <ul><li>Precision globale</li><li>Ventilation par categorie (quels sujets sont les plus forts ?)</li><li>Distribution de confiance (la haute confiance est-elle correlee a l&#39;exactitude ?)</li></ul></li><li>Lancez TruthfulQA sur le meme modele</li><li>Comparez les graphiques radar entre les suites</li><li>Si le temps le permet, executez les memes suites sur un second modele</li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Dans quelles categories le modele obtient-il les meilleurs/pires resultats ?</li><li>Le modele est-il plus precis sur les questions &quot;faciles&quot; ? Verifiez les donnees de logprob.</li><li>Comment la precision sur TruthfulQA se compare-t-elle a ARC ? Qu&#39;est-ce que cela revele sur les differents types de connaissances ?</li><li>Si vous deviez deployer ce modele, quelles faiblesses vous preoccuperaient le plus ?</li></ul><hr><h3 id="exercice-4-espaces-d-embedding" tabindex="-1">Exercice 4 : Espaces d&#39;embedding <a class="header-anchor" href="#exercice-4-espaces-d-embedding" aria-label="Permalink to &quot;Exercice 4 : Espaces d&#39;embedding&quot;">​</a></h3><p><strong>Objectif :</strong> Explorer comment les modeles representent le sens sous forme de vecteurs.</p><p><strong>Duree :</strong> 45 minutes</p><p><strong>Prerequis :</strong> Un modele d&#39;embedding (par ex. <code>nomic-embed-text</code>)</p><p><strong>Instructions :</strong></p><ol><li>Ouvrez la page <strong>Embeddings</strong></li><li>Generez les embeddings de ces trois phrases individuellement : <ul><li>&quot;The cat sat on the mat&quot;</li><li>&quot;A feline rested on the rug&quot;</li><li>&quot;The stock market crashed today&quot;</li></ul></li><li>Comparez la phrase 1 et la phrase 2 (la similarite devrait etre elevee)</li><li>Comparez la phrase 1 et la phrase 3 (la similarite devrait etre faible)</li><li>Observez les scores de similarite cosinus</li><li>Testez maintenant des cas limites : <ul><li>&quot;I love this movie&quot; vs &quot;I hate this movie&quot; (meme sujet, sentiment oppose)</li><li>&quot;Bank of the river&quot; vs &quot;Bank account&quot; (meme mot, sens different)</li></ul></li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Pourquoi &quot;cat/mat&quot; et &quot;feline/rug&quot; sont-ils similaires malgre des mots differents ?</li><li>Le modele capture-t-il les differences de sentiment ? Que dit le score de similarite ?</li><li>Comment l&#39;ambiguite lexicale (&quot;bank&quot;) affecte-t-elle la similarite des embeddings ?</li><li>Comment ces embeddings seraient-ils utiles pour un moteur de recherche ?</li></ul><hr><h3 id="exercice-5-construire-un-outil" tabindex="-1">Exercice 5 : Construire un outil <a class="header-anchor" href="#exercice-5-construire-un-outil" aria-label="Permalink to &quot;Exercice 5 : Construire un outil&quot;">​</a></h3><p><strong>Objectif :</strong> Creer un outil personnalise qu&#39;un modele de langage peut appeler.</p><p><strong>Duree :</strong> 60 minutes</p><p><strong>Prerequis :</strong> Un modele compatible avec le tool calling (verifiez le badge dans le Model Browser)</p><p><strong>Instructions :</strong></p><ol><li>Ouvrez le <strong>Tool Workshop</strong></li><li>Partez du template &quot;Calculator&quot; pour comprendre le format</li><li>Creez un nouvel outil a partir de zero : <ul><li><strong>Nom :</strong> <code>word_count</code></li><li><strong>Description :</strong> &quot;Count the number of words in a given text&quot;</li><li><strong>Parametres :</strong> <code>text</code> (string, requis)</li><li><strong>Implementation :</strong> Ecrivez la fonction JavaScript</li></ul></li><li>Visualisez le JSON Schema genere automatiquement</li><li>Retournez dans Chat Diagnostics et demandez : &quot;How many words are in the sentence: The quick brown fox jumps over the lazy dog?&quot;</li><li>Observez l&#39;appel d&#39;outil dans l&#39;onglet <strong>Tools</strong></li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Comment le modele decide-t-il d&#39;appeler un outil plutot que de repondre directement ?</li><li>Que se passe-t-il si la description de l&#39;outil est vague ?</li><li>Que se passe-t-il si vous modifiez la description pour la rendre trompeuse ?</li><li>Pourquoi le JSON Schema est-il important pour le modele ?</li></ul><hr><h3 id="exercice-6-curation-de-donnees-d-entrainement" tabindex="-1">Exercice 6 : Curation de donnees d&#39;entrainement <a class="header-anchor" href="#exercice-6-curation-de-donnees-d-entrainement" aria-label="Permalink to &quot;Exercice 6 : Curation de donnees d&#39;entrainement&quot;">​</a></h3><p><strong>Objectif :</strong> Constituer un petit jeu de donnees curate a partir d&#39;interactions avec l&#39;IA.</p><p><strong>Duree :</strong> 60 minutes</p><p><strong>Prerequis :</strong> LLMxRay avec quelques sessions de chat prealables</p><p><strong>Instructions :</strong></p><ol><li>Utilisez Chat Diagnostics pour mener 5 a 10 conversations sur un sujet precis (par ex. &quot;Explain Python concepts&quot;)</li><li>Ouvrez la page <strong>AI Training</strong></li><li>Passez en revue les paires d&#39;entrainement collectees</li><li>Pour chaque paire, decidez : Accepter (bonne reponse), Rejeter (mauvaise reponse) ou Editer (reponse ameliorable)</li><li>Etiquetez les paires acceptees par sous-theme (par ex. &quot;loops&quot;, &quot;functions&quot;, &quot;classes&quot;)</li><li>Exportez le jeu de donnees curate</li><li>Examinez le format d&#39;export</li></ol><p><strong>Questions pour les etudiants :</strong></p><ul><li>Qu&#39;est-ce qui distingue une &quot;bonne&quot; paire d&#39;entrainement d&#39;une &quot;mauvaise&quot; ?</li><li>Comment ce jeu de donnees serait-il utilise pour fine-tuner un modele ?</li><li>Quels biais pourraient exister dans vos donnees curatees ?</li><li>Combien de paires faudrait-il pour un fine-tuning significatif ?</li></ul><hr><h2 id="configuration-materielle" tabindex="-1">Configuration materielle <a class="header-anchor" href="#configuration-materielle" aria-label="Permalink to &quot;Configuration materielle&quot;">​</a></h2><h3 id="minimum-petits-modeles-uniquement" tabindex="-1">Minimum (petits modeles uniquement) <a class="header-anchor" href="#minimum-petits-modeles-uniquement" aria-label="Permalink to &quot;Minimum (petits modeles uniquement)&quot;">​</a></h3><ul><li><strong>RAM :</strong> 8 Go</li><li><strong>Stockage :</strong> 10 Go disponibles</li><li><strong>GPU :</strong> Non requis (l&#39;inference CPU fonctionne)</li><li><strong>Modeles :</strong> Modeles de 1B a 3B parametres (par ex. <code>llama3.2:1b</code>)</li></ul><h3 id="recommande-pour-tous-les-exercices" tabindex="-1">Recommande (pour tous les exercices) <a class="header-anchor" href="#recommande-pour-tous-les-exercices" aria-label="Permalink to &quot;Recommande (pour tous les exercices)&quot;">​</a></h3><ul><li><strong>RAM :</strong> 16 Go</li><li><strong>Stockage :</strong> 20 Go disponibles</li><li><strong>GPU :</strong> 6+ Go de VRAM (inference sensiblement plus rapide)</li><li><strong>Modeles :</strong> Jusqu&#39;a 7B-8B parametres</li></ul><h3 id="configuration-en-salle-informatique" tabindex="-1">Configuration en salle informatique <a class="header-anchor" href="#configuration-en-salle-informatique" aria-label="Permalink to &quot;Configuration en salle informatique&quot;">​</a></h3><ul><li><strong>Installation par etudiant :</strong> Chaque machine execute Ollama + LLMxRay de maniere independante</li><li><strong>Serveur Ollama partage :</strong> Une machine puissante execute Ollama, les etudiants s&#39;y connectent via les parametres LLMxRay (modifier l&#39;URL Ollama). Necessite un acces reseau sur le port 11434.</li><li><strong>Deploiement Docker :</strong> Utilisez <code>docker compose</code> pour des environnements homogenes :</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.example.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><h2 id="pistes-d-evaluation" tabindex="-1">Pistes d&#39;evaluation <a class="header-anchor" href="#pistes-d-evaluation" aria-label="Permalink to &quot;Pistes d&#39;evaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Exercice</th><th>Methode d&#39;evaluation</th></tr></thead><tbody><tr><td>Exploration des tokens</td><td>Rapport ecrit comparant les effets de la temperature avec captures d&#39;ecran</td></tr><tr><td>Comparaison de modeles</td><td>Tableau de donnees avec metriques + analyse de 500 mots</td></tr><tr><td>Benchmark</td><td>Presentation de diapositives avec graphiques radar</td></tr><tr><td>Espaces d&#39;embedding</td><td>Notebook Jupyter avec matrices de similarite et analyse</td></tr><tr><td>Construire un outil</td><td>Demonstration en direct de l&#39;outil fonctionnel + revue de code</td></tr><tr><td>Donnees d&#39;entrainement</td><td>Jeu de donnees exporte + reflexion sur les choix de curation</td></tr></tbody></table><h2 id="obtenir-de-l-aide" tabindex="-1">Obtenir de l&#39;aide <a class="header-anchor" href="#obtenir-de-l-aide" aria-label="Permalink to &quot;Obtenir de l&#39;aide&quot;">​</a></h2><ul><li><strong><a href="https://github.com/LogneBudo/llmxray/discussions/categories/help" target="_blank" rel="noreferrer">GitHub Discussions</a></strong> — Posez vos questions dans la categorie Help</li><li><strong><a href="https://lognebudo.github.io/llmxray/docs/en/guide/" target="_blank" rel="noreferrer">Documentation</a></strong> — Guide utilisateur complet avec presentation des fonctionnalites</li><li><strong><a href="https://github.com/LogneBudo/llmxray/issues/new?template=bug-report.yml" target="_blank" rel="noreferrer">Rapports de bugs</a></strong> — Signalez les problemes avec nos modeles structures</li></ul><hr><p><em>Vous utilisez LLMxRay dans votre cours ? Nous aimerions en entendre parler. Ouvrez une <a href="https://github.com/LogneBudo/llmxray/discussions/categories/model-insights" target="_blank" rel="noreferrer">discussion Model Insights</a> et partagez votre experience.</em></p>',77)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
